Q: How to capture process-space key events in OSX command-line tool, CoreFoundation, C API? A: <p>Here is a bit of individual research that resulted in 120 lines of functional code, which captures keyboard events from the terminal window running the command-line program. There is a block argument in dispatch_sync() function, which I don't particularly like, because it is a &quot;polluted C&quot;, but I have no idea how to write that part in plain C. The program compiles in gcc (macOS command-line tools) as well as in Xcode and runs in macOS 15.5, Arm64.</p>
<p>Here's the code. I don't how much of a good programming practice it is, but I'd like to share it, at least for the reason that the question has not received a more straightforward answer so far:</p>
<pre><code>//  cfmn.c
//  gcc -Wall -o cfmn cfmn.c -framework ApplicationServices
//_______________________________________________________________________________

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;ApplicationServices/ApplicationServices.h&gt;

static dispatch_queue_t  lock;
static CFMutableArrayRef events;

//_______________________________________________________________________________
CGEventRef callback(CGEventTapProxy proxy,
                    CGEventType type,
                    CGEventRef event,
                    void *refcon)
{
    CGEventFlags flags = CGEventGetFlags(event);
    // Exclude command or control modifiers
    if (((flags &amp; kCGEventFlagMaskCommand) == 0)&amp;&amp;((flags &amp; kCGEventFlagMaskControl) == 0)) {
        if (type == kCGEventKeyDown) {
            CGKeyCode keyCode = (CGKeyCode)CGEventGetIntegerValueField(event, kCGKeyboardEventKeycode);
            printf (&quot;Key code: %d\n&quot;, keyCode);
            if (keyCode == 53)
                CFRunLoopStop(CFRunLoopGetCurrent());
            // unelegant part of code ...
            dispatch_sync(lock, ^{
                CFArrayAppendValue(events, event);
            });
            ;
        }
        return NULL; // do not return event
    }
    return event;    // return event unmodified
}
//_______________________________________________________________________________

int main(int argc, const char * argv[]) {

        char appname[256] = {0};    
        pid_t frontmostPid = 0;
        void* userinfo = NULL;

        lock = dispatch_queue_create(&quot;lock&quot;, NULL);
        events = CFArrayCreateMutable(kCFAllocatorDefault,
                                      0,
                                      &amp;kCFTypeArrayCallBacks);



        CFArrayRef windowList = CGWindowListCopyWindowInfo(  kCGWindowListOptionOnScreenOnly,
                                                            kCGNullWindowID);

          if (windowList != NULL) {
              CFIndex count = CFArrayGetCount(windowList);
              for (CFIndex i = 0; i &lt; count; i++) {
                  CFDictionaryRef windowInfo = CFArrayGetValueAtIndex(windowList, i);
                  CFNumberRef layerNum = CFDictionaryGetValue(windowInfo, kCGWindowLayer);
                  int layer = 0;
                  if (layerNum &amp;&amp; CFNumberGetValue(layerNum, kCFNumberIntType, &amp;layer) &amp;&amp; layer == 0) {
                      CFNumberRef pidNum = CFDictionaryGetValue(windowInfo, kCGWindowOwnerPID);
                      if (pidNum) {
                          CFNumberGetValue(pidNum, kCFNumberIntType, &amp;frontmostPid);
                      }
                      CFStringRef ownerName = CFDictionaryGetValue(windowInfo, kCGWindowOwnerName);
                      if (ownerName) {
                          CFStringGetCString(ownerName,
                                          appname,
                                          sizeof(appname),
                                          kCFStringEncodingUTF8);
                      }
                      break;
                  }
              }
              CFRelease(windowList);
          }


        printf(&quot;\n|- - - - - Main Loop Test - - - - -|\n&quot;);
        printf(&quot;|- - press any key; &lt;esc&gt;=quit- - -|\n&quot;);
        printf(&quot;Frontmost App: %s;  &quot;,appname);
        printf(&quot;PID: %d\n&quot;,     frontmostPid );

        CGEventMask   eventMask = CGEventMaskBit(kCGEventKeyDown);

        CFMachPortRef eventPort = CGEventTapCreateForPid(frontmostPid,
                                                        kCGHeadInsertEventTap,
                                                        kCGEventTapOptionDefault,
                                                        eventMask,
                                                        callback,
                                                        userinfo);
        if (eventPort == NULL) {
            fprintf(stderr, &quot;NULL event port\n&quot;);
            return 1;
        }

        CFRunLoopSourceRef runLoopSource = CFMachPortCreateRunLoopSource(kCFAllocatorDefault,
                                                                         eventPort,
                                                                         0);
        CFRunLoopAddSource(CFRunLoopGetCurrent(), runLoopSource, kCFRunLoopCommonModes);
        CGEventTapEnable(eventPort, true);
        CFRunLoopRun();

        printf   (&quot;Program stopped\n\n&quot;);
        CFRelease(runLoopSource);
        CFRelease(eventPort);
        CFRelease(events);
        dispatch_release(lock);

    return 0;
}
</code></pre>

Q: Match case statement with multiple &#39;or&#39; conditions in each case A: <p><a href="https://docs.python.org/3/whatsnew/3.10.html#guard" rel="nofollow noreferrer"><code>case</code>s accept a &quot;guard&quot; clause</a>, which you can use for this purpose:</p>
<pre><code>match x:
    case w if w in a:
        return &quot;132&quot;
    case w if w in b:
        return &quot;564&quot;
    case w if w in c:
        return &quot;798&quot;
</code></pre>
<p>the <code>w</code> here actually captures the value of <code>x</code>, part of the syntax here too, but it's more useful in some other fancy <em>cases</em> listed on the linked whatsnew page.</p>

Q: How can I update field state directly, quickly from AI stream? A: <p>I've never used useFormContext, but I think if you wrap the code in a useEffect hook it should work.</p>
<p>Something like:</p>
<pre><code>useEffect(() =&gt; {
    for await (const delta of readStreamableValue(output)) {
      if (delta) {
        const value = getValues(&quot;editor&quot;);
        setValue(&quot;editor&quot;, value + delta);
      }
    }
}, output);
</code></pre>
